"""Small summary landing page; fetch only a selected trial and selected step."""
import json,sys
from pathlib import Path

def physical_gallery(root):
    setups=json.loads((root/'scene_setup.json').read_text())
    names=json.dumps([s['scene_name'] for s in setups]).replace('</','<\\/')
    page=r'''<!doctype html><meta charset="utf-8"><title>Task3 物理状态</title><style>body{font:16px system-ui;margin:24px}select,button{font:inherit;padding:8px}img{max-width:100%}</style><h1>六条件物理路径、可见距离与姿态</h1><p>选择一个场景查看。数据来自 MuJoCo，未连接实体机械狗。图中距离曲线缺口表示目标不可见，红虚线为1m。</p><select id="scene"><option value="">选择场景</option></select><button onclick="show()">查看</button><div id="plot"></div><script>const names=__NAMES__;names.forEach(n=>{let o=document.createElement('option');o.value=n;o.textContent=n;document.getElementById('scene').appendChild(o)});function show(){let n=document.getElementById('scene').value;if(!n)return;document.getElementById('plot').innerHTML='<h2>'+n+'</h2><img src="physical_plots/'+encodeURIComponent(n)+'.png">'}</script>'''
    (root/'physical_state_browser.html').write_text(page.replace('__NAMES__',names))

def build(root):
    report=json.loads((root/'analysis.json').read_text());overview={k:report[k] for k in ('expected','completed','audit_pass','all_complete','conditions')}
    data=json.dumps({'root':str(root.resolve()),'overview':overview,'trials':report['trials']},ensure_ascii=False).replace('</','<\\/')
    page=r'''<!doctype html><meta charset="utf-8"><title>Task3 实验汇总</title><style>body{font:16px system-ui;background:#121923;color:#e5edf5;margin:24px;max-width:1300px}select,button,input{font:inherit;padding:8px;margin:5px}table{border-collapse:collapse}td,th{border:1px solid #455;padding:8px}img{max-width:48%;max-height:380px;margin:5px}pre{white-space:pre-wrap;background:#202b38;padding:12px;max-height:400px;overflow:auto}a{color:#9bd4ff}details{margin:14px 0}.camera-panel{border:1px solid #455;border-radius:8px;padding:12px;margin:16px 0}.camera-panel h3{margin:0 0 8px}.camera-controls{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:6px}.camera-controls input{width:90px}#current-camera{display:flex;gap:10px;flex-wrap:wrap}#current-camera img{width:calc(50% - 10px);max-width:640px;height:auto;margin:0;max-height:none}@media(max-width:700px){#current-camera img{width:100%;max-width:100%}}.thumbs img{max-width:180px}.notice{color:#f5c36a}</style><h1>Task3 实验汇总</h1><p>默认只显示汇总。按条件、结局筛选，选择一个 trial 后查看；图像与完整上下文按需展开。</p><div id="status"></div><div id="metrics"></div><p><a href="terrain_gallery.html">全部地形图片</a> · <a href="../../terrain_design_v3/index.html">新版地形设计 v3</a> · <a href="FINAL_REPORT.md">完整报告</a> · <a href="evaluation_metrics.json">最终指标</a> · <a href="difficulty_classification.json">完成后的任务难度划分</a> · <a href="RUN_STATUS.json">实时运行状态</a></p><select id="mode"><option value="">全部传感器</option><option>rgb</option><option>rgbd</option></select><select id="history"><option value="">全部上下文</option><option>current</option><option>first_current</option><option>all_history</option></select><select id="ending"><option value="">全部结局</option><option>success_visible_near</option><option>premature_stop</option><option>budget_exhausted</option><option>out_of_bounds</option><option>context_limit</option><option>invalid_model_output</option><option>gpu_memory_limit</option><option>disk_space_limit</option><option>running</option></select><select id="trial"></select><button id="load">打开所选 trial</button><div id="detail"></div><script>const D=__DATA__;const $=id=>document.getElementById(id);const esc=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const pre=x=>'<pre>'+esc(typeof x==='string'?x:JSON.stringify(x,null,2))+'</pre>';const path=p=>p.startsWith(D.root+'/')?p.slice(D.root.length+1):p;const pic=p=>'<img loading="lazy" src="'+esc(path(p))+'">';const get=async p=>{let r=await fetch(p,{cache:'no-store'});if(!r.ok)throw Error(p+' HTTP '+r.status);return r.json()};let T=null;let generation=0;let overview=D.overview;$('status').innerHTML='<b>'+ (overview.all_complete?'整轮实验完成':'实验尚未完成，不能将当前比例作为最终成功率')+'</b><p>'+overview.completed+' / '+overview.expected+' trial；审计 '+overview.audit_pass+'</p>';$('metrics').innerHTML='<table><tr><th>传感器</th><th>上下文</th><th>完成</th><th>成功</th><th>资源终止</th><th>完整条件成功率</th></tr>'+overview.conditions.map(c=>'<tr><td>'+c.mode+'</td><td>'+c.horizon+'</td><td>'+c.completed+'</td><td>'+c.success+'</td><td>'+c.resource_limits+'</td><td>'+(overview.all_complete?(100*c.observed_completion_fraction).toFixed(1)+'%':'待整轮完成')+'</td></tr>').join('')+'</table>';function filter(){let selected=D.trials.filter(t=>(!$('mode').value||t.mode===$('mode').value)&&(!$('history').value||t.horizon===$('history').value)&&(!$('ending').value||t.termination===$('ending').value));$('trial').innerHTML='<option value="">选择 trial</option>'+selected.map(t=>'<option value="'+D.trials.indexOf(t)+'">'+esc(t.scene+' / '+t.mode+' / '+t.horizon+' / '+t.termination)+'</option>').join('')};for(let id of ['mode','history','ending'])$(id).onchange=filter;filter();async function load(){if($('trial').value==='')return;let id=++generation;let s=D.trials[+$('trial').value];let base=s.mode+'/'+s.horizon+'/trials/'+s.scene+'/';$('detail').innerHTML='正在读取所选 trial…';try{let [frames,gate,initial,response]=await Promise.all([get(base+'observations.json'),get(base+'approach_gate.json'),get(base+'initialization.json'),fetch(base+'trace.jsonl',{cache:'no-store'})]);let traces=(await response.text()).trim().split('\n').flatMap(l=>{try{return [JSON.parse(l)]}catch{return []}});if(id!==generation)return;T={s,base,frames,gate,initial,traces:traces.filter(t=>t.phase==='vlm_autonomous')};$('detail').innerHTML='<h2>'+esc(s.scene+' / '+s.mode+' / '+s.horizon)+'</h2>'+pre(s)+'<p>初始相机深度距离 '+initial.initial_depth_camera_range_m.toFixed(3)+' m；目标消失类型 '+esc(gate.loss_kind)+'。</p><details open><summary>初始观测（current组未提供给模型，仅供评估）</summary>'+pic(frames[0].rgb_path)+pic(frames[0].depth_path)+'</details><details open><summary>实际路径、可见距离和姿态图</summary>'+pic('physical_plots/'+s.scene+'.png')+'</details><section class="camera-panel"><h3>当前相机 RGB 与深度</h3><div class="camera-controls"><button id="prev">上一步</button><input id="step" type="number" min="0" max="'+Math.max(0,T.traces.length-1)+'" value="0" aria-label="自主决策记录序号"><button id="next">下一步</button><span> 共 '+T.traces.length+' 次自主决策（序号从0开始）</span></div><div id="current-camera"></div></section><div id="decision"></div>';let saved=null;try{saved=JSON.parse(sessionStorage.getItem('task3-view:'+location.pathname))}catch{};if(saved&&saved.trial===$('trial').value)$('step').value=Math.max(0,Math.min(T.traces.length-1,saved.step||0));$('step').onchange=show;$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);show()}catch(e){$('detail').textContent=e.message}}async function show(){try{sessionStorage.setItem('task3-view:'+location.pathname,JSON.stringify({mode:$('mode').value,history:$('history').value,ending:$('ending').value,trial:$('trial').value,step:+$('step').value}))}catch{};let t=T.traces[+$('step').value];if(!t){$('decision').textContent='尚无自主决策记录';return}$('current-camera').innerHTML=pic(T.frames[t.frame_before].rgb_path)+pic(T.frames[t.frame_before].depth_path);let parsed=t.decision;let html='<h3>动作 '+t.step+'：'+esc(t.action)+'；结局 '+esc(t.termination||'继续')+'</h3><p>'+esc(parsed?.decision_rationale||'本次无有效动作输出')+'</p>'+pre({context:t.context,evidence_frames:parsed?.evidence_frames,evidence_sources:parsed?.evidence_sources,before_evaluator:t.before_evaluator,after_evaluator:t.after_evaluator,actual_displacement_xy_m:t.actual_displacement_xy_m});for(let [i,rel] of t.inference_records.entries()){let folder=T.base+rel.replace(/output.json$/,'');let [messages,context,output]=await Promise.all([get(folder+'messages.json'),get(folder+'context.json'),get(folder+'output.json')]);let images=messages.messages[1].content.filter(b=>b.type==='image');html+='<details open><summary>推理 '+(i+1)+'：实际输入的 '+context.input_frame_count+' 帧 / '+context.input_tokens+' token</summary>'+pre(context)+'<div class="thumbs">'+images.map(im=>pic(im.image_path)).join('')+'</div><a href="'+folder+'rendered_prompt.txt">完整提示词</a> · <a href="'+folder+'network_input.json">实际网络输入与hash</a>'+pre(messages)+'</details><details open><summary>推理 '+(i+1)+'：完整原始输出与公开策略说明</summary>'+pre(output)+'</details>'}$('decision').innerHTML=html}function move(n){$('step').value=Math.max(0,Math.min(T.traces.length-1,+$('step').value+n));show()}$('load').onclick=load;try{let saved=JSON.parse(sessionStorage.getItem('task3-view:'+location.pathname));if(saved){for(let id of ['mode','history','ending'])$(id).value=saved[id]||'';filter();$('trial').value=saved.trial;if($('trial').value!=='')load()}}catch{};</script>'''
    rendered=page.replace('__DATA__',data)
    if not (root/'terrain_gallery.html').exists():
        rendered=rendered.replace('<a href="terrain_gallery.html">全部地形图片</a> · ', '')
    temporary=root/'index.html.tmp';temporary.write_text(rendered);temporary.replace(root/'index.html')
if __name__=='__main__':
    root=Path(sys.argv[1]).resolve();build(root);physical_gallery(root)
